const QUESTION_STAGES=[{level:1,tier:1,name:'Foundation'},{level:5,tier:2,name:'Explorer'},{level:10,tier:3,name:'Problem solver'},{level:18,tier:4,name:'Strategist'},{level:26,tier:5,name:'Master reasoning'}];
function questionStage(level=playerLevel()){return [...QUESTION_STAGES].reverse().find(s=>level>=s.level)||QUESTION_STAGES[0]}
// Explicit advanced items use upper-primary concepts with more reasoning, rather than obscure trivia.
const ADVANCED_ROWS=[
['english',4,'“Unlike the noisy oval, the library was a harbour.” What is the effect of “harbour” here?','It suggests a calm, sheltered place.','It proves the library contains boats.','It is a literal measurement of noise.','It tells us the library is outdoors.','The contrast with the noisy oval supports a metaphor of refuge and calm. A metaphor need not describe a literal harbour.'],
['english',5,'A report claims homework improves results because the top-scoring class had more homework. What important information is missing?','Whether other differences between the classes could explain the results.','The colour of each homework folder.','Whether the report has a short title.','Whether all students use the same pen.','One comparison does not isolate a cause. Prior achievement, support and other class differences could affect results.'],
['science',4,'Two cups hold equal volumes of water at 70°C. One is wrapped; one is not. What best tests the wrapping?','Measure both temperatures after the same time in the same room.','Use ice water in the unwrapped cup.','Leave one cup in sunlight and one indoors.','Measure only the wrapped cup before the test.','A fair comparison changes the wrapping while controlling starting temperature, volume, time and surroundings.'],
['science',5,'A plant grows poorly under a red lamp. Can one test prove that red light prevents plant growth?','No; repeat with several plants and control other growth conditions.','Yes; one plant proves the rule for every species.','Yes; red is always harmful to plants.','No; observations can never provide evidence.','A single observation can have several explanations. Repetition, a comparison group and controlled water and temperature strengthen the evidence.'],
['history',4,'A diary and a newspaper describe the same arrival differently. What should a historian do first?','Compare their authors, dates, purposes and supporting evidence.','Keep only the account written in neater handwriting.','Assume both sources must be false.','Choose whichever story is more exciting.','Different perspectives can explain differences. Source context and corroborating evidence help historians judge what each account supports.'],
['history',5,'A 1901 poster celebrates Federation but says nothing about people excluded from voting. What is the strongest conclusion?','It shows a celebratory viewpoint, so other sources are needed to study exclusion.','No one was excluded because the poster does not mention it.','All Australians agreed with the poster.','The poster cannot tell historians anything useful.','Silence in a source does not prove something did not happen. Its purpose shapes what it emphasises and omits.'],
['geography',4,'Two towns receive the same yearly rainfall, but one has long dry periods. Why might water planning differ?','Rainfall timing and storage needs can differ despite equal annual totals.','Equal totals guarantee equal water supply every day.','The town with the shorter name needs less storage.','Yearly rainfall totals describe every daily pattern.','An annual total hides seasonal variation. Storage must bridge dry periods and account for local demand.'],
['geography',5,'A new road shortens travel but crosses a wetland. Which comparison best supports a balanced decision?','Compare access benefits with habitat effects and alternative routes.','Count only the number of cars expected.','Ignore the wetland because it has no houses.','Assume every shorter route is the best choice.','Geographical decisions involve trade-offs between people, environments and possible alternatives; one measure cannot capture every effect.'],
['civics',4,'A school vote is 60% in favour of a change that blocks wheelchair access. What should the school do?','Revise the plan to protect access while considering the vote.','Implement it because any majority removes all responsibilities.','Stop allowing students to express views.','Ignore every student because the vote was not unanimous.','Democratic participation matters alongside inclusion and responsibilities. A majority does not remove the need for accessible participation.'],
['civics',5,'A council has money for only one project. What makes a proposal stronger?','Evidence of community needs, costs, benefits and who may miss out.','Only the loudest speaker supporting it.','A promise that no trade-offs exist.','A colourful logo without cost information.','Limited resources require comparing opportunity costs and distribution of benefits. Evidence makes those choices more transparent.'],
['digital',4,'A loop repeats “move 2 steps, turn right” four times. The character ends where it started. What shape did it trace?','A square with sides of 2 steps.','A triangle with sides of 4 steps.','A straight line of 8 steps.','A circle with no corners.','Four equal movements separated by four right-angle turns trace a square and return the character to its initial position.'],
['digital',5,'A bridge model fails when heavy loads are placed in its centre. What is the best next design step?','Identify the failure point, change one feature, then repeat the same load test.','Change every feature and use a much lighter test load.','Hide the failed result and declare success.','Choose a new colour without testing strength.','Controlled iteration connects a design change to its effect. Using the same load test makes the comparison meaningful.'],
['arts',4,'A rhythm has four beats per bar. Three crotchets are followed by two quavers. Does it fill one bar?','Yes: 3 + ½ + ½ = 4 beats.','No: each quaver lasts 2 beats.','No: five notes must always mean five beats.','Yes: every group of notes fills a bar.','Duration determines the beat total, not just note count. Two quavers together last one crotchet beat.'],
['arts',5,'A film shows a scene from low down with loud, low music. What interpretation is best supported?','The choices may make the character seem powerful or threatening.','They prove the character is kind in every scene.','Camera angle and music cannot affect meaning.','They reveal the exact height of the actor.','Camera angles and sound are expressive choices. A low angle and strong low sounds can suggest power, while context still matters.'],
['sports',4,'A team can pass quickly but often loses the ball near goal. Which practice best targets the problem?','Small-sided games requiring controlled passes under defensive pressure.','Only running laps without a ball.','Only practising the victory celebration.','Removing all defenders from every practice forever.','Practice should reproduce the skill and decision demands causing the difficulty. Controlled passing under pressure directly targets possession.'],
['sports',5,'An athlete feels dizzy while exercising in hot weather. What should the team do?','Stop activity, move to a cool place and tell a responsible adult promptly.','Encourage the athlete to ignore dizziness.','Offer an energy drink and insist on finishing.','Leave the athlete alone until the match ends.','Dizziness is a warning sign. Stopping exercise and involving an adult allows the situation to be assessed and appropriate help arranged.'],
['languages',4,'In one language “luma” means sun and “lumari” means suns; “tova” means tree. If the same plural rule applies, what means trees?','Tovari','Ritova','Tovaluma','Lumatova','The examples suggest adding ri to the singular word. Applying that pattern to tova gives tovari; the rule is limited to this invented language.'],
['languages',5,'A greeting is suitable with close friends but sounds rude in a formal meeting. What does this show?','Appropriate language depends on audience, relationship and context.','One greeting must have exactly the same effect everywhere.','Formal meetings cannot include greetings.','The speaker must never learn another greeting.','Meaning includes social context. Register and conventions can change with relationships and settings.'],
['general',4,'A museum ticket costs $12, while a $30 family pass covers four people. For three visitors, which is cheaper?','The family pass saves $6.','Three tickets save $6.','They cost the same.','The family pass saves $18.','Three single tickets cost 3 × $12 = $36. The $30 family pass covers all three and costs $6 less.'],
['general',5,'A headline says “All plastics are recyclable” but the local guide accepts only some types. What is the most useful action?','Check the local collection rules for the exact item.','Put every plastic item in recycling because of the headline.','Assume no plastic can ever be recycled.','Sort only by the colour of the item.','A material may be technically recyclable without being accepted by a local collection system. Specific local instructions guide correct disposal.']
];
for(const[id,tier,prompt,a,b,c,d,why]of ADVANCED_ROWS)BANK[id].push([prompt,[a,b,c,d],0,why,null,null,null,tier]);
for(let i=0;i<24;i++){
 const price=40+8*i,discount=price*.25,paid=price-discount,delivery=6+i%4;
 BANK.maths.push([`A kit costs $${price}. It is reduced by 25%, then $${delivery} delivery is added. What is the total?`,['$'+(paid+delivery),'$'+paid,'$'+(discount+delivery),'$'+(price+delivery)],0,`First find 25% of $${price}: $${discount}. Subtract it to get $${paid}, then add $${delivery} delivery: $${paid+delivery}.`,null,null,'discount-delivery',4]);
 const total=120+i*12,a=total/3,b=(total-a)/4,left=total-a-b;
 BANK.maths.push([`A club spends one third of $${total} on equipment, then one quarter of the remaining money on transport. How much is left?`,['$'+left,'$'+(total-total/3-total/4),'$'+(total-a),'$'+(total-b)],0,`Equipment costs $${a}, leaving $${total-a}. Transport costs one quarter of this remainder, $${b}. The amount left is $${left}.`,null,null,'fraction-remainder',5]);
 const x=3+i,y=x+4,totalLegs=2*x+4*y;
 BANK.logic.push([`A yard has ${x+y} animals: chickens with 2 legs and dogs with 4 legs. There are ${totalLegs} legs. How many dogs are there?`,[y,x,y+1,y-1].map(String),0,`If every animal had 2 legs, there would be ${(x+y)*2} legs. The extra ${totalLegs-(x+y)*2} legs come from dogs, with 2 extra legs each. Divide by 2 to get ${y} dogs.`,null,null,'animals-legs',4]);
 const start=5+i,finish=(start+3)*2-4;
 BANK.logic.push([`A mystery number has 3 added, is doubled, then has 4 subtracted. The result is ${finish}. What was the starting number?`,[start,start+1,start+3,start*2].map(String),0,`Work backwards: add 4 to ${finish}, divide by 2, then subtract 3. (${finish} + 4) ÷ 2 − 3 = ${start}.`,null,null,'reverse-machine',5]);
}
function itemDifficulty(item){const q=item.q;if(q[7])return q[7];if(['volume','discount','alternating','growing-gaps','number-machine'].includes(q[6]))return 3;if(q[6])return 2;if(/best support|interpret|infer|evidence|subordinate|passive voice|controlled|fair test|reliable|bias|perspective|conclusion|opportunity cost/i.test(q[0]))return 3;if(/why|explain|\bthen\b|percent|percentage|fraction|\d.*\d|contrast|effect|compare/i.test(q[0]))return 2;return 1}
const ungradedDeck=buildQuestionDeck;
buildQuestionDeck=function(subject){const tier=questionStage().tier,deck=ungradedDeck(subject),fresh=deck.filter(item=>!profile.questionSeen[questionKey(item)]),seen=deck.filter(item=>profile.questionSeen[questionKey(item)]);return [...fresh.map((item,i)=>({item,i,cost:Math.abs(itemDifficulty(item)-tier)+(itemDifficulty(item)>tier?1:0)})).sort((a,b)=>a.cost-b.cost||a.i-b.i).map(x=>x.item),...seen]};

QUESTION_COUNT=Object.values(BANK).reduce((n,list)=>n+list.length,0);

